// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title  RWAVault
/// @notice Single vault backing all AchRWA synthetic pairs.
///         Users send USDC (Arc native, 18 dec) to buy synths.
///         Users return synths to redeem USDC at current oracle price.
///         0.3% fee on every buy and redeem. Fees and reserve are separate buckets.

interface IAchRWAOracle {
    enum Category { Stock, Commodity, Forex }

    struct RWAPair {
        uint256  pairId;
        string   name;
        string   symbol;
        Category category;
        string   priceSource;
        string   description;
        address  synth;
        uint256  price;
        uint256  lastUpdated;
        uint256  maxStaleness;
        uint256  maxDeviation;
        bool     active;
        bool     frozen;
        uint256  createdAt;
    }

    function getPair(uint256 pairId)  external view returns (RWAPair memory);
    function getAllPairs()             external view returns (RWAPair[] memory);
    function pairCount()              external view returns (uint256);
    function getPrice(uint256 pairId) external view returns (
        uint256 price, uint256 lastUpdated, uint256 age, bool isStale
    );
}

interface IRWASynth {
    function mint(address to,   uint256 amount) external;
    function burn(address from, uint256 amount) external;
    function balanceOf(address a)               external view returns (uint256);
    function totalSupply()                      external view returns (uint256);
    function symbol()                           external view returns (string memory);
}

contract RWAVault {

    uint256 public constant FEE_BPS         = 30;
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant MAX_TX_AMOUNT   = 10_000_000 * 1e18;

    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED     = 2;
    uint256 private _status;

    modifier nonReentrant() {
        require(_status != _ENTERED, "RWAVault: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    address public owner;
    address public pendingOwner;

    IAchRWAOracle public immutable oracle;

    bool    public paused;
    uint256 public totalReserve;
    uint256 public accumulatedFees;

    mapping(uint256 => uint256) public pairReserve;
    mapping(uint256 => uint256) public pairFees;

    uint256 public totalBuys;
    uint256 public totalRedeems;
    uint256 public totalFeesEarned;
    uint256 public totalVolumeUSDC;

    event ReserveDeposited(address indexed depositor, uint256 amount, uint256 newTotalReserve, uint256 timestamp);
    event SynthBought(uint256 indexed pairId, address indexed buyer, string symbol, uint256 usdcIn, uint256 fee, uint256 reserveAdded, uint256 synthMinted, uint256 price, uint256 timestamp);
    event SynthRedeemed(uint256 indexed pairId, address indexed redeemer, string symbol, uint256 synthBurned, uint256 grossUsdc, uint256 fee, uint256 usdcOut, uint256 price, uint256 timestamp);
    event FeesWithdrawn(address indexed to, uint256 amount, uint256 timestamp);
    event EmergencyReserveWithdrawn(address indexed to, uint256 amount, uint256 timestamp);
    event Paused  (address indexed by, uint256 timestamp);
    event Unpaused(address indexed by, uint256 timestamp);
    event OwnershipTransferInitiated(address indexed newOwner, uint256 timestamp);
    event OwnershipTransferred(address indexed oldOwner, address indexed newOwner, uint256 timestamp);

    constructor(address _oracle) {
        require(_oracle != address(0), "RWAVault: zero oracle");
        oracle  = IAchRWAOracle(_oracle);
        owner   = msg.sender;
        _status = _NOT_ENTERED;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "RWAVault: not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "RWAVault: paused");
        _;
    }

    // Ownership

    /// @notice Step 1 of two-step ownership transfer.
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "RWAVault: zero address");
        pendingOwner = newOwner;
        emit OwnershipTransferInitiated(newOwner, block.timestamp);
    }

    /// @notice Step 2 — new owner accepts. Prevents accidental lockout.
    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "RWAVault: not pending owner");
        emit OwnershipTransferred(owner, pendingOwner, block.timestamp);
        owner        = pendingOwner;
        pendingOwner = address(0);
    }

    // Emergency

    function pause() external onlyOwner {
        require(!paused, "RWAVault: already paused");
        paused = true;
        emit Paused(msg.sender, block.timestamp);
    }

    function unpause() external onlyOwner {
        require(paused, "RWAVault: not paused");
        paused = false;
        emit Unpaused(msg.sender, block.timestamp);
    }

    /// @notice Last-resort reserve withdrawal. Vault must be paused first.
    function emergencyWithdrawReserve(address to, uint256 amount) external onlyOwner nonReentrant {
        require(paused,                 "RWAVault: must pause first");
        require(to   != address(0),     "RWAVault: zero address");
        require(amount > 0,             "RWAVault: zero amount");
        require(amount <= totalReserve, "RWAVault: exceeds reserve");
        totalReserve -= amount;
        (bool ok,) = to.call{value: amount}("");
        require(ok, "RWAVault: transfer failed");
        emit EmergencyReserveWithdrawn(to, amount, block.timestamp);
    }

    // Reserve

    /// @notice Fund the vault reserve. On Arc, native token IS USDC — send msg.value.
    function depositReserve() external payable onlyOwner nonReentrant {
        require(msg.value > 0, "RWAVault: zero deposit");
        totalReserve += msg.value;
        emit ReserveDeposited(msg.sender, msg.value, totalReserve, block.timestamp);
    }

    /// @notice Withdraw accumulated fees only. Cannot touch reserve.
    function withdrawFees(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0,                "RWAVault: zero amount");
        require(amount <= accumulatedFees, "RWAVault: exceeds accumulated fees");
        accumulatedFees -= amount;
        (bool ok,) = owner.call{value: amount}("");
        require(ok, "RWAVault: transfer failed");
        emit FeesWithdrawn(owner, amount, block.timestamp);
    }

    // Core

    /// @notice Buy synthetic token by sending USDC (Arc native).
    /// @param pairId   Target pair.
    /// @param minSynth Minimum synth to receive. Compute via quoteBuy() first.
    function buy(uint256 pairId, uint256 minSynth)
        external
        payable
        nonReentrant
        whenNotPaused
    {
        require(msg.value > 0,              "RWAVault: zero USDC sent");
        require(msg.value <= MAX_TX_AMOUNT, "RWAVault: exceeds max tx amount");

        IAchRWAOracle.RWAPair memory pair = oracle.getPair(pairId);
        require(pair.active,              "RWAVault: pair not active");
        require(pair.synth != address(0), "RWAVault: pair has no synth");

        (uint256 price,,, bool isStale) = oracle.getPrice(pairId);
        require(!isStale,  "RWAVault: oracle price is stale");
        require(price > 0, "RWAVault: no price available");

        uint256 fee         = (msg.value * FEE_BPS) / BPS_DENOMINATOR;
        uint256 netUsdc     = msg.value - fee;
        require(netUsdc > 0, "RWAVault: net amount zero after fee");

        uint256 synthAmount = (netUsdc * 1e18) / price;
        require(synthAmount > 0,         "RWAVault: synth rounds to zero");
        require(synthAmount >= minSynth, "RWAVault: slippage exceeded");

        totalReserve        += netUsdc;
        accumulatedFees     += fee;
        pairReserve[pairId] += netUsdc;
        pairFees[pairId]    += fee;
        totalFeesEarned     += fee;
        totalVolumeUSDC     += msg.value;
        totalBuys++;

        IRWASynth(pair.synth).mint(msg.sender, synthAmount);

        emit SynthBought(pairId, msg.sender, pair.symbol, msg.value, fee, netUsdc, synthAmount, price, block.timestamp);
    }

    /// @notice Redeem synth tokens for USDC at current oracle price.
    ///         No approve() needed — burn() is vault-only and pulls directly from balanceOf.
    /// @param pairId      Target pair.
    /// @param synthAmount Synth tokens to burn.
    /// @param minUsdc     Minimum USDC to receive. Compute via quoteRedeem() first.
    function redeem(uint256 pairId, uint256 synthAmount, uint256 minUsdc)
        external
        nonReentrant
        whenNotPaused
    {
        require(synthAmount > 0,              "RWAVault: zero synth amount");
        require(synthAmount <= MAX_TX_AMOUNT, "RWAVault: exceeds max tx amount");

        IAchRWAOracle.RWAPair memory pair = oracle.getPair(pairId);
        require(pair.active,              "RWAVault: pair not active");
        require(pair.synth != address(0), "RWAVault: pair has no synth");

        require(
            IRWASynth(pair.synth).balanceOf(msg.sender) >= synthAmount,
            "RWAVault: insufficient synth balance"
        );

        (uint256 price,,, bool isStale) = oracle.getPrice(pairId);
        require(!isStale,  "RWAVault: oracle price is stale");
        require(price > 0, "RWAVault: no price available");

        uint256 grossUsdc = (synthAmount * price) / 1e18;
        require(grossUsdc > 0, "RWAVault: USDC out rounds to zero");

        uint256 fee    = (grossUsdc * FEE_BPS) / BPS_DENOMINATOR;
        uint256 netOut = grossUsdc - fee;
        require(netOut > 0,             "RWAVault: net USDC zero after fee");
        require(netOut >= minUsdc,      "RWAVault: slippage exceeded");
        require(netOut <= totalReserve, "RWAVault: insufficient reserve");

        totalReserve    -= netOut;
        accumulatedFees += fee;
        totalFeesEarned += fee;
        totalVolumeUSDC += grossUsdc;
        pairFees[pairId] += fee;
        totalRedeems++;

        if (pairReserve[pairId] >= netOut) {
            pairReserve[pairId] -= netOut;
        } else {
            pairReserve[pairId] = 0;
        }

        IRWASynth(pair.synth).burn(msg.sender, synthAmount);

        (bool ok,) = msg.sender.call{value: netOut}("");
        require(ok, "RWAVault: USDC transfer failed");

        emit SynthRedeemed(pairId, msg.sender, pair.symbol, synthAmount, grossUsdc, fee, netOut, price, block.timestamp);
    }

    // Quotes

    /// @notice Quote synth out for a given USDC input. Call before buy().
    function quoteBuy(uint256 pairId, uint256 usdcIn) external view
        returns (uint256 synthOut, uint256 fee, uint256 netUsdc, uint256 price, bool isStale)
    {
        require(usdcIn > 0, "RWAVault: zero input");
        (price,,, isStale) = oracle.getPrice(pairId);
        fee      = (usdcIn * FEE_BPS) / BPS_DENOMINATOR;
        netUsdc  = usdcIn - fee;
        synthOut = price > 0 ? (netUsdc * 1e18) / price : 0;
    }

    /// @notice Quote USDC out for a given synth amount. Call before redeem().
    /// @return usdcOut   USDC you would receive after fee.
    /// @return fee       Protocol fee (0.3%).
    /// @return grossUsdc USDC value before fee.
    /// @return price     Oracle price used.
    /// @return isStale   True if oracle price is stale.
    /// @return reserveOk True if vault reserve covers this redeem.
    function quoteRedeem(uint256 pairId, uint256 synthAmount) external view
        returns (uint256 usdcOut, uint256 fee, uint256 grossUsdc, uint256 price, bool isStale, bool reserveOk)
    {
        require(synthAmount > 0, "RWAVault: zero input");
        (price,,, isStale) = oracle.getPrice(pairId);
        grossUsdc = price > 0 ? (synthAmount * price) / 1e18 : 0;
        fee       = (grossUsdc * FEE_BPS) / BPS_DENOMINATOR;
        usdcOut   = grossUsdc > fee ? grossUsdc - fee : 0;
        reserveOk = usdcOut <= totalReserve;
    }

    // View

    function getVaultBalance() external view returns (
        uint256 rawBalance, uint256 reserve, uint256 fees,
        uint256 _totalBuys, uint256 _totalRedeems, uint256 _totalFeesEarned, uint256 _totalVolumeUSDC
    ) {
        return (address(this).balance, totalReserve, accumulatedFees, totalBuys, totalRedeems, totalFeesEarned, totalVolumeUSDC);
    }

    /// @notice Reserve health ratio.
    /// @return ratio          1e18 = 100% backed. Below 1e18 = undercollateralized.
    /// @return _totalReserve  Current USDC reserve.
    /// @return totalSynthValue Total USD value of all outstanding synths.
    /// @return isHealthy      True if reserve >= outstanding synth value.
    function reserveRatio() external view returns (
        uint256 ratio, uint256 _totalReserve, uint256 totalSynthValue, bool isHealthy
    ) {
        IAchRWAOracle.RWAPair[] memory allPairs = oracle.getAllPairs();
        uint256 synthValue = 0;

        for (uint256 i = 0; i < allPairs.length; i++) {
            IAchRWAOracle.RWAPair memory p = allPairs[i];
            if (!p.active || p.synth == address(0)) continue;
            uint256 supply = IRWASynth(p.synth).totalSupply();
            if (supply == 0) continue;
            (uint256 price,,, bool stale) = oracle.getPrice(p.pairId);
            if (price == 0 || stale) continue;
            synthValue += (supply * price) / 1e18;
        }

        _totalReserve   = totalReserve;
        totalSynthValue = synthValue;

        if (synthValue == 0) {
            ratio     = type(uint256).max;
            isHealthy = true;
        } else {
            ratio     = (totalReserve * 1e18) / synthValue;
            isHealthy = ratio >= 1e18;
        }
    }

    function getPairStats(uint256 pairId) external view returns (
        uint256 _pairReserve, uint256 _pairFees, uint256 synthTotalSupply, uint256 synthValueUSD, uint256 price, bool isStale
    ) {
        IAchRWAOracle.RWAPair memory pair = oracle.getPair(pairId);
        require(pair.synth != address(0), "RWAVault: pair has no synth");
        (price,,, isStale) = oracle.getPrice(pairId);
        synthTotalSupply   = IRWASynth(pair.synth).totalSupply();
        synthValueUSD      = price > 0 ? (synthTotalSupply * price) / 1e18 : 0;
        _pairReserve       = pairReserve[pairId];
        _pairFees          = pairFees[pairId];
    }

    function getAllPairStats() external view returns (
        uint256[] memory pairIds, string[] memory symbols, uint256[] memory reserves,
        uint256[] memory fees, uint256[] memory supplies, uint256[] memory values,
        uint256[] memory prices, bool[] memory staleFlags
    ) {
        IAchRWAOracle.RWAPair[] memory allPairs = oracle.getAllPairs();
        uint256 n = allPairs.length;

        pairIds    = new uint256[](n); symbols    = new string[] (n);
        reserves   = new uint256[](n); fees       = new uint256[](n);
        supplies   = new uint256[](n); values     = new uint256[](n);
        prices     = new uint256[](n); staleFlags = new bool[]   (n);

        for (uint256 i = 0; i < n; i++) {
            IAchRWAOracle.RWAPair memory p = allPairs[i];
            pairIds[i]  = p.pairId;
            symbols[i]  = p.symbol;
            reserves[i] = pairReserve[p.pairId];
            fees[i]     = pairFees[p.pairId];
            if (p.synth != address(0)) supplies[i] = IRWASynth(p.synth).totalSupply();
            (uint256 price,,, bool stale) = oracle.getPrice(p.pairId);
            prices[i]     = price;
            staleFlags[i] = stale;
            values[i]     = price > 0 ? (supplies[i] * price) / 1e18 : 0;
        }
    }

    function getUserPortfolio(address user) external view returns (
        uint256[] memory pairIds, string[] memory symbols, uint256[] memory synthBalances,
        uint256[] memory usdValues, uint256[] memory prices, bool[] memory staleFlags
    ) {
        require(user != address(0), "RWAVault: zero address");
        IAchRWAOracle.RWAPair[] memory allPairs = oracle.getAllPairs();
        uint256 n = allPairs.length;

        pairIds       = new uint256[](n); symbols       = new string[] (n);
        synthBalances = new uint256[](n); usdValues     = new uint256[](n);
        prices        = new uint256[](n); staleFlags    = new bool[]   (n);

        for (uint256 i = 0; i < n; i++) {
            IAchRWAOracle.RWAPair memory p = allPairs[i];
            pairIds[i] = p.pairId;
            symbols[i] = p.symbol;
            if (p.synth != address(0)) synthBalances[i] = IRWASynth(p.synth).balanceOf(user);
            (uint256 price,,, bool stale) = oracle.getPrice(p.pairId);
            prices[i]     = price;
            staleFlags[i] = stale;
            usdValues[i]  = price > 0 ? (synthBalances[i] * price) / 1e18 : 0;
        }
    }

    /// @notice Direct sends treated as reserve top-up. Owner only.
    receive() external payable nonReentrant {
        require(msg.sender == owner, "RWAVault: only owner can send directly");
        require(msg.value > 0,       "RWAVault: zero value");
        totalReserve += msg.value;
        emit ReserveDeposited(msg.sender, msg.value, totalReserve, block.timestamp);
    }

    fallback() external {
        revert("RWAVault: function not found");
    }
}
